#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>

int main(int argc, char *argv[]) {
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    char *endptr = NULL;
    long long n = strtoll(argv[1], &endptr, 10);
    if (endptr == argv[1] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    if (n < 1) {
        puts("BAD_INPUT");
        return 0;
    }
    if (n > 1000000000LL) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    long long original = n;
    long long steps = 0;
    while (n != 1) {
        if ((n & 1LL) == 0) {
            n = n >> 1;               // even case
        } else {
            if (n > 1000000000000000LL) { // overflow guard before 3n+1
                puts("OVERFLOW_GUARD");
                return 0;
            }
            n = n * 3 + 1;            // odd case
        }
        steps++;
        if (steps > 999999LL) {
            puts("STEP_LIMIT_EXCEEDED");
            return 0;
        }
    }

    printf("n=%ld steps=%ld\n", original, steps);
    return 0;
}
